-- STELLAR LEGACY V81 • CONFIGURACAO OFICIAL (PROJETO stellar-legacy)
-- CONFIG APENAS: NAO altera game_saves, perfis, usuarios, clãs ou recibos de recompensa.
-- Pode ser reaplicado: valores idempotentes e versao de portais sobe somente na alteracao.
BEGIN;
-- Backup de configuracoes por chave, somente para restauração administrativa; nunca dados pessoais.
CREATE TABLE IF NOT EXISTS public.stellar_balance_backup_v81 (
 kind text NOT NULL, row_key text NOT NULL, original jsonb NOT NULL,
 saved_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(kind,row_key)
);
ALTER TABLE public.stellar_balance_backup_v81 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.stellar_balance_backup_v81 FROM PUBLIC,anon,authenticated;
INSERT INTO public.stellar_balance_backup_v81(kind,row_key,original)
 SELECT 'npc',npc_key,to_jsonb(t) FROM public.game_npc_config_v1811 t ON CONFLICT DO NOTHING;
INSERT INTO public.stellar_balance_backup_v81(kind,row_key,original)
 SELECT 'spawn',map_id||':'||npc_key,to_jsonb(t) FROM public.game_map_npc_spawns_v1811 t ON CONFLICT DO NOTHING;
INSERT INTO public.stellar_balance_backup_v81(kind,row_key,original)
 SELECT 'map',map_id,to_jsonb(t) FROM public.game_map_config_v1814 t ON CONFLICT DO NOTHING;
INSERT INTO public.stellar_balance_backup_v81(kind,row_key,original)
 SELECT 'mission_category',category,to_jsonb(t) FROM public.game_mission_category_v1815 t ON CONFLICT DO NOTHING;
INSERT INTO public.stellar_balance_backup_v81(kind,row_key,original)
 SELECT 'mission_custom',mission_id,to_jsonb(t) FROM public.game_mission_custom_v1815 t ON CONFLICT DO NOTHING;
INSERT INTO public.stellar_balance_backup_v81(kind,row_key,original)
 SELECT 'portal',id::text,to_jsonb(t) FROM public.galaxy_gate_config_v1906 t ON CONFLICT DO NOTHING;
INSERT INTO public.stellar_balance_backup_v81(kind,row_key,original)
 SELECT 'runtime_meta',config_key,to_jsonb(t) FROM public.game_runtime_meta_v1810 t ON CONFLICT DO NOTHING;
