UPDATE public.game_npc_config_v1811 n SET hp=u.hp,shield=u.shield,damage=u.damage,
 speed=u.speed,xp=u.xp,credits=u.credits,stl=u.stl,resources=u.resources,
 respawn_min_ms=CASE WHEN n.npc_key='apexOverlord' THEN 360000 ELSE n.respawn_min_ms END,
 respawn_max_ms=CASE WHEN n.npc_key='apexOverlord' THEN 600000 ELSE n.respawn_max_ms END,
 updated_at=now()
FROM updates u WHERE n.npc_key=u.npc_key;
-- Chefe exclusivo no X-7 (nao remove os demais NPCs dos setores).
UPDATE public.game_map_npc_spawns_v1811 SET spawn_count=2,enabled=true,updated_at=now()
 WHERE map_id='x7' AND npc_key='apexOverlord';
UPDATE public.game_map_npc_spawns_v1811 SET spawn_count=0,enabled=false,updated_at=now()
 WHERE map_id='b43' AND npc_key='apexOverlord';
-- X-7 niv 15 e canon do world SQL e do grafo V45.1. Sem endurecer acesso dos saves existentes.
UPDATE public.game_map_config_v1814 SET min_level=15,updated_at=now() WHERE map_id='x7';
-- Ajustes das metas por janela. Preservar missoes ja aceitas com definition congelada.
UPDATE public.game_mission_category_v1815 SET config=(config||'{"hunt_normal_target":70,"hunt_boss_target":20,"combo_normal_target":35,"combo_boss_target":6}'::jsonb),
  reward_factor=0.58,updated_at=now() WHERE category='daily';
UPDATE public.game_mission_category_v1815 SET config=jsonb_set(config,'{steps}','[8,18,35,70,110,160,220,350,550,800]'::jsonb),
  reward_factor=0.86,updated_at=now() WHERE category='weekly';
UPDATE public.game_mission_category_v1815 SET config=jsonb_set(config,'{steps}','[80,180,350,700,1100,1600,2200,3500,5500,8000]'::jsonb),
  reward_factor=1.05,updated_at=now() WHERE category='monthly';
