-- O editor ADM do Portal deve reconhecer novas espécies mantendo a função e sua autenticação intactas.
DO $v81$
DECLARE source_code text; old_list text:='ARRAY[''streuner'',''recruitStreuner'',''aiderStreuner'',''lordakia'',''saimon'',''mordon'',''devolarium'',''sibelon'',''bossLordakia'',''bossSaimon'',''bossMordon'',''bossDevolarium'',''bossSibelon'']'; new_list text:='ARRAY[''streuner'',''recruitStreuner'',''aiderStreuner'',''bossStreuner'',''lordakia'',''bossLordakia'',''saimon'',''bossSaimon'',''mordon'',''bossMordon'',''devolarium'',''bossDevolarium'',''sibelon'',''bossSibelon'',''emberFang'',''bossEmberFang'',''ironWasp'',''bossIronWasp'',''riftMauler'',''bossRiftMauler'',''obsidianPike'',''bossObsidianPike'',''sentinelScavenger'',''sentinelScout'',''sentinelSupport'',''riftScout'',''bossRiftScout'',''voidCorsair'',''bossVoidCorsair'',''nexusWarden'',''bossNexusWarden'',''astralReaper'',''bossAstralReaper'']';
BEGIN
 SELECT pg_get_functiondef('public.admin_update_galaxy_gate_config_v1906(text,jsonb)'::regprocedure) INTO source_code;
 IF position(old_list IN source_code)>0 THEN
  EXECUTE replace(source_code,old_list,new_list);
 ELSIF position(new_list IN source_code)=0 THEN
  RAISE EXCEPTION 'Validador de NPCs dos Portais mudou; interrompendo em seguranca.';
 END IF;
END $v81$;
-- Versionamento dos snapshots: NPC, mundo (spawns), sistemas (missoes).
UPDATE public.game_runtime_meta_v1810 SET version=version+1,updated_at=now() WHERE config_key IN ('npc','world','systems');
-- Aborta se o chefe ou algum dos NPCs nao foi configurado corretamente.
DO $verify$
BEGIN
 IF (SELECT count(*) FROM public.game_npc_config_v1811 WHERE enabled)=0 THEN RAISE EXCEPTION 'NPCs ausentes'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.game_map_npc_spawns_v1811 WHERE map_id='x7' AND npc_key='apexOverlord' AND enabled AND spawn_count=2)
 THEN RAISE EXCEPTION 'X-7 nao esta com exatamente 2 Apex'; END IF;
 IF (SELECT count(*) FROM public.game_mission_custom_v1815 WHERE mission_id LIKE 'v81_%' AND enabled)<8 THEN RAISE EXCEPTION 'Missoes V81 incompletas'; END IF;
END $verify$;
COMMIT;
